            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Bu dünyaya inanma, vefasın bulam sanma. Ömrün veren ziyana, çoğu pişman içinde.", Author = "Yunus Emre" },
