            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Dört kitabın manasını okudum tahsil ettim. Aşka gelince gördüm, bir uzun hece imiş.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Eğer aşkı sever isen can olasın. Kamu derdine hem derman olasın.", Author = "Yunus Emre" },
