            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Hiç hata yapmayan insan, hiçbir şey yapmayan insandır; ve hayatta en büyük hata, kendini hatasız sanmaktır.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Hoştur bana senden gelen. Ya gonca gül,yahut diken. Ya hayattır, yahut kefen. Nârın da hoş, nurun da hoş. Kahrın da hoş, lütfun da hoş.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "İlim ilim bilmektir, ilim kendin bilmektir, sen kendin bilmez isen, ya nice okumaktır.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Keleci bilen kişiünüñ yüzini ak ede bir söz. Sözi bişürüp deyenüñ işini sağ ede bir söz Söz ola kese savaşı, söz ola bitüre başı Söz ola agulu aşı bal ile yağ ede bir söz.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Mal sahibi mülk sahibi, Hani bunun ilk sahibi, Mal da yalan mülk de yalan , Var gel biraz da sen oyalan.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Maharet güzeli görebilmektir, sevmenin sırrına erebilmektir. Cihan, Alem herkes bilsin ki şunu; En büyük ibadet sevebilmektir.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Miskin Adem oğlanı, nefse zebun olmuştur. Hayvan canavar gibi, otlamağa kalmıştır.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Mü'min olanların çoktur cefâsı, Ahirette olur zevk-u sefâsı, On sekiz bin âlemin Mustafâ'sı, Adı güzel, kendi güzel Muhammed", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Nazar eyle itiri Pazar eyle götürü Yaradılanı hoş gör Yaradandan ötürü", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Olsun be aldırma Yaradan yardır. Sanma ki zalimin ettiği kârdır. Mazlumun ahı indirir şâhı. Her şeyin bir vakti vardır.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Ölümden ne korkarsın, korkma ebedi varsın.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Sabah mezarlığa vardım, baktım herkes ölmüş yatar, her biri çâresiz olup, ömrünü yitirmiş yatar.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Sabır saadeti ebedi kalır Sabır kimde ise o nasib alır.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Sanırdım kendim ayrıyım Dost ayrıdır, ben gayrıyım Beni bu hayale salan Bu sıfat-ı hayvan imiş..", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Sen doğru ol da varsın sanan eğri sansın. Lâkin sakın unutma ki; Sen kendini bir şey sanmadığın sürece doğru insansın.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Sevelim sevilelim, dünya kimseye kalmaz..", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Sular hep aktı geçti, kurudu vakti geçti, Nice han nice sultan tahtı bıraktı geçti, Dünya bir penceredir, her gelen baktı geçti...", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Türlü türlü cefanın adını aşk koymuşlar.Aşka münkir ademi bu meydandan sürmüşler.", Author = "Yunus Emre" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Yunus_Emre", Text = "Ya Rabbena hayreyle, Muhammed'e yâr eyle, Kabrimizi nur eyle, Kabre vardığım gece.", Author = "Yunus Emre" },
